from itertools import product
SETS = "BCPU"   # Boxes, Cartons, Papers, Utensils
types = [frozenset(s for s, bit in zip(SETS, bits) if bit) for bits in product([0, 1], repeat=4)]
types = [t for t in types if t]
def some(m, x, y): return any(x in t and y in t for t in m)
def all_(m, x, y): return all(y in t for t in m if x in t)
def statements(m): return some(m, "B", "C") and all_(m, "C", "P") and some(m, "C", "U")
I_always = II_always = True
for mask in range(1, 1 << len(types)):
    m = [t for i, t in enumerate(types) if mask >> i & 1]
    if not statements(m):
        continue
    I_always &= not some(m, "B", "U")
    II_always &= some(m, "P", "U")
opts = {"A": (False, True), "B": (True, False), "C": (True, True), "D": (False, False)}
result = (I_always, II_always)

match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

slots = ["TL", "MM", "MR", "BL", "BM", "BR"]
f2 = {"TL": "X", "MM": "2", "MR": "L", "BL": "K", "BM": "8", "BR": "W"}
f3 = {"TL": "W", "MM": "L", "MR": "2", "BL": "T", "BM": "X", "BR": "8"}
