from fractions import Fraction
toks = ["18", "-", "23", "*", "455", "/", "7", "+", "28"]
def val(ts):
    nums = [Fraction(int(x)) for x in ts[0::2]]; ops = ts[1::2]
    # BODMAS: * and / first
    n, o = [nums[0]], []
    for op, x in zip(ops, nums[1:]):
        if op == "*": n[-1] *= x
        elif op == "/": n[-1] /= x
        else: n.append(x); o.append(op)
    r = n[0]
    for op, x in zip(o, n[1:]):
        r = r + x if op == "+" else r - x
    return r
def swap(a, b):
    return [b if t == a else a if t == b else t for t in toks]
pairs = {"A": ("/", "-"), "B": ("-", "+"), "C": ("+", "*"), "D": ("-", "*")}
opts = {k: val(swap(*p)) == 377 for k, p in pairs.items()}
result = True

match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

